// The static build for GitHub Pages: `npm run build:pages` writes _site/, a copy of the site that runs without the
// Node server. The game server's own modules (server/arena.js, the games, the AI, the challenges...) are bundled into
// js/local-server.js and run in the page, connected to the site by pages/local-io.js instead of socket.io, so every
// rule, timer and AI move is the real code. With one player per page the static build offers the matches vs the AI
// (and the tutorials); online matchmaking and challenge links need the real server and are hidden there.
//
// The generated files (index.html, config, engines, theme, sound list, manifest) come from the real server: it is
// started on a free port and asked for them, then their paths are made relative, so the site works under any
// sub-path (https://<user>.github.io/<repo>/).
process.env.DEV_MODE = 'false';
process.env.SHOW_WAITING_COUNTS = 'false';
process.env.PUBLIC_URL = '';

const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const OUT = path.join(ROOT, process.argv[2] || '_site');
const PUBLIC = path.join(ROOT, 'public');
const REPO_URL = 'https://github.com/oxkryn23-art/arcade-games';

// ---- a tiny CommonJS bundler for the server modules ----
const OVERRIDES = {
  crypto: path.join(ROOT, 'pages', 'shims.js'),
  [path.join(ROOT, 'server', 'config.js')]: path.join(ROOT, 'pages', 'config.js'),
};
function resolveFrom(dir, spec) {
  if (!spec.startsWith('.')) {
    if (OVERRIDES[spec]) return OVERRIDES[spec];
    throw new Error(`build-pages: no browser stand-in for require('${spec}')`);
  }
  const base = path.resolve(dir, spec);
  for (const p of [base, `${base}.js`, path.join(base, 'index.js')]) {
    if (fs.existsSync(p) && fs.statSync(p).isFile()) return OVERRIDES[p] || p;
  }
  throw new Error(`build-pages: cannot resolve ${spec} from ${dir}`);
}
function bundle(entries) {
  const mods = new Map();   // abs path -> { id, src, map }
  const visit = (file) => {
    if (mods.has(file)) return mods.get(file).id;
    const mod = { id: path.relative(ROOT, file).replace(/\\/g, '/'), src: fs.readFileSync(file, 'utf8'), map: {} };
    mods.set(file, mod);
    // requires named in comments are not code
    const code = mod.src.split('\n').map((l) => l.replace(/^\s*\/\/.*$/, '').replace(/\s\/\/\s.*$/, '')).join('\n');
    for (const [, spec] of code.matchAll(/\brequire\(\s*['"]([^'"]+)['"]\s*\)/g)) mod.map[spec] = visit(resolveFrom(path.dirname(file), spec));
    return mod.id;
  };
  const ids = Object.fromEntries(Object.entries(entries).map(([name, file]) => [name, visit(file)]));
  const defs = [...mods.values()].map((m) => `defs[${JSON.stringify(m.id)}] = [${JSON.stringify(m.map)}, function (module, exports, require) {\n${m.src}\n}];`).join('\n');
  return `// Generated by tools/build-pages.js from the server's own modules. Do not edit.
(function () {
'use strict';
// Node timers have unref(); the browser's are numbers. These keep the server code unchanged.
const T = (h) => ({ h, unref() { return this; }, ref() { return this; }, hasRef() { return true; } });
const H = (t) => (t && typeof t === 'object' ? t.h : t);
const setTimeout = (f, ms, ...a) => T(window.setTimeout(f, ms, ...a));
const setInterval = (f, ms, ...a) => T(window.setInterval(f, ms, ...a));
const clearTimeout = (t) => window.clearTimeout(H(t));
const clearInterval = (t) => window.clearInterval(H(t));
const defs = {}, cache = {};
function load(id) {
  if (cache[id]) return cache[id].exports;
  const [map, fn] = defs[id];
  const m = { exports: {} }; cache[id] = m;
  fn.call(m.exports, m, m.exports, (spec) => load(map[spec]));
  return m.exports;
}
${defs}
window.LocalServer = { ${Object.entries(ids).map(([n, id]) => `${n}: load(${JSON.stringify(id)})`).join(', ')} };
})();
`;
}

// ---- the offline page: the play buttons go to the AI, online play and challenges are hidden ----
function offlineIndex(html) {
  const swap = (from, to) => { if (!html.includes(from)) throw new Error(`build-pages: index.html changed, missing: ${from}`); html = html.split(from).join(to); };
  html = html.replace(/(\s(?:src|href))="\/(?!\/)/g, '$1="./');
  if (!/<link rel="stylesheet" href="\.\/css\/arcade\.css[^"]*">/.test(html)) throw new Error('build-pages: index.html changed, missing arcade.css');
  html = html.replace(/(<link rel="stylesheet" href="\.\/css\/arcade\.css[^"]*">)/, '$1\n  <link rel="stylesheet" href="./css/pages.css">');
  swap('<script src="./socket.io/socket.io.min.js"></script>', '<script src="./js/local-server.js"></script>\n  <script src="./js/local-io.js"></script>');
  swap('<button class="btn btn-play btn-big" id="btnPlay">Play online</button>', '<button class="btn btn-play btn-big hidden" id="btnPlay" hidden>Play online</button>');
  swap('<button class="btn btn-ghost btn-big" id="btnDemo">Play vs AI</button>', '<button class="btn btn-play btn-big" id="btnDemo">Play vs AI</button>');
  swap('<button class="btn btn-play btn-big play-go" id="btnFind">Find an opponent</button>', '<button class="btn btn-play btn-big play-go hidden" id="btnFind" hidden>Find an opponent</button>');
  swap('<button class="btn btn-ghost btn-big play-ai" id="btnAi">Play vs AI</button>', '<button class="btn btn-play btn-big play-ai" id="btnAi">Play vs AI</button>');
  swap('<p class="side-sub" id="sideSub">Matched with the first player who shares one of your games.</p>', '<p class="side-sub" id="sideSub">You play against the AI, a random one of your games.</p>');
  html = html.replace(/<button([^>]*?)\sdata-challenge>/g, '<button$1 data-challenge hidden>');
  swap('<div class="side-sep" aria-hidden="true"></div>', '');
  const note = `<span class="foot-note"><span>Static demo on GitHub Pages: the server runs in your browser, so you play against the AI. Online 1v1 and challenge links need the Node server: <a href="${REPO_URL}">source on GitHub</a>.</span></span>`;
  html = html.replace(/(<footer class="site-foot">[\s\S]*?)(<\/footer>)/g, `$1${note}$2`);
  return html;
}

async function main() {
  const { server } = require('../server/index.js');
  await new Promise((res) => server.listen(0, '127.0.0.1', res));
  const base = `http://127.0.0.1:${server.address().port}`;
  const get = async (p) => { const r = await fetch(base + p); if (!r.ok) throw new Error(`build-pages: ${p} -> ${r.status}`); return r.text(); };
  try {
    fs.rmSync(OUT, { recursive: true, force: true });
    fs.cpSync(PUBLIC, OUT, { recursive: true });
    const write = (p, text) => { fs.mkdirSync(path.dirname(path.join(OUT, p)), { recursive: true }); fs.writeFileSync(path.join(OUT, p), text); };
    const edit = (p, fn) => write(p, fn(fs.readFileSync(path.join(OUT, p), 'utf8')));
    const must = (text, re, to, what) => { if (!re.test(text)) throw new Error(`build-pages: ${what} not found`); return text.replace(re, to); };

    write('index.html', offlineIndex(await get('/')));
    write('js/config.js', (await get('/js/config.js')).replace(/"\/(js|css|covers)\//g, '"$1/'));
    write('js/engines.js', await get('/js/engines.js'));
    write('css/theme.css', await get('/css/theme.css'));
    write('sfx/manifest.json', await get('/sfx/manifest.json'));
    const manifest = JSON.parse(await get('/site.webmanifest'));
    manifest.start_url = './';
    manifest.icons = manifest.icons.map((i) => ({ ...i, src: i.src.replace(/^\//, '') }));
    write('site.webmanifest', JSON.stringify(manifest));

    edit('js/app.js', (s) => must(s, /`\/covers\//g, '`covers/', 'app.js cover path'));
    edit('js/sound.js', (s) => must(s.replace(/'\/sfx\//g, "'sfx/"), /`\/sfx\//g, '`sfx/', 'sound.js sfx path'));
    edit('css/fonts.css', (s) => must(s, /url\(\/fonts\//g, 'url(../fonts/', 'fonts.css font path'));

    write('js/local-server.js', bundle({ arena: path.join(ROOT, 'server', 'arena.js') }));
    fs.copyFileSync(path.join(ROOT, 'pages', 'local-io.js'), path.join(OUT, 'js', 'local-io.js'));
    fs.copyFileSync(path.join(ROOT, 'pages', 'pages.css'), path.join(OUT, 'css', 'pages.css'));
    write('.nojekyll', '');

    // nothing may still point at the site root (it would miss the repo's sub-path on GitHub Pages)
    const leftovers = [];
    const scan = (dir) => {
      for (const f of fs.readdirSync(dir, { withFileTypes: true })) {
        const p = path.join(dir, f.name);
        if (f.isDirectory()) scan(p);
        else if (/\.(html|css|js|webmanifest)$/.test(f.name)) {
          const text = fs.readFileSync(p, 'utf8');
          if (/(?:src|href)="\/(?!\/)|url\(\/(?!\/)|['"`]\/(?:js|css|sfx|covers|fonts|api|socket\.io)\//.test(text)) leftovers.push(path.relative(OUT, p));
        }
      }
    };
    scan(OUT);
    const allowed = new Set(['js/app.js']);   // its /api/challenge fetch only runs for challenge links (hidden here)
    const bad = leftovers.filter((f) => !allowed.has(f.replace(/\\/g, '/')));
    if (bad.length) throw new Error(`build-pages: root paths left in ${bad.join(', ')}`);
    console.log(`Static site written to ${path.relative(ROOT, OUT)}/`);
  } finally {
    server.close();
  }
}

main().catch((e) => { console.error(e.message || e); process.exitCode = 1; });
